descendant_processes.command_line:
"C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe" -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$ErrorActionPreference='Stop'
$evidenceDir='C:\Projects\llm_mvp_core\docs\plans\evidence\extension-full-readiness-dual-path\scenario-execution\frdp-p01-codex-ui-input-surface-discovery-before-send\micro-step-05-webview-metadata-feasibility'
$targetPid=13508
$ts=(Get-Date).ToString('o')
$all = Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine,CreationDate
$byParent = @{}
foreach($p in $all){
  $pp=[int]$p.ParentProcessId
  if(-not $byParent.ContainsKey($pp)){ $byParent[$pp]=@() }
  $byParent[$pp] += $p
}
$desc = New-Object System.Collections.Generic.List[object]
$q = New-Object System.Collections.Generic.Queue[int]
$q.Enqueue($targetPid)
while($q.Count -gt 0){
  $parent = $q.Dequeue()
  if($byParent.ContainsKey($parent)){
    foreach($c in $byParent[$parent]){
      $desc.Add($c)
      $q.Enqueue([int]$c.ProcessId)
    }
  }
}
function Convert-Proc($p){
  if($null -eq $p){ return $null }
  $cmd=[string]$p.CommandLine
  $flags = @()
  foreach($flag in @('--remote-debugging-port','--remote-debugging-address','--inspect','--inspect-brk')){
    if($cmd -match [regex]::Escape($flag)){ $flags += $flag }
  }
  [ordered]@{
    process_id=[int]$p.ProcessId
    parent_process_id=[int]$p.ParentProcessId
    name=$p.Name
    executable_path=$p.ExecutablePath
    command_line=$p.CommandLine
    creation_date_raw=$p.CreationDate
    remote_debugging_flags_present=$flags
    codex_app_family_hint=([bool](($p.Name -match 'Codex') -or ($p.ExecutablePath -match 'Codex') -or ($p.CommandLine -match 'Codex')))
  }
}
$target = $all | Where-Object { [int]$_.ProcessId -eq $targetPid } | Select-Object -First 1
$out=[ordered]@{
  artifact='micro-step-05-process-metadata'
  micro_step='Микро-шаг 05'
  collected_at=$ts
  read_only=$true
  target_pid=$targetPid
  process_metadata_available=($null -ne $target)
  target_process=(Convert-Proc $target)
  descendant_count=$desc.Count
  descendant_processes=@($desc | ForEach-Object { Convert-Proc $_ })
  forbidden_actions_observed='No injection, restart, debugger attach, Runtime.evaluate, Input.*, UI mutation, or UIA traversal was used.'
  product_readiness_claim=$false
  literal='не доказывает готовность продукта'
}
$path=Join-Path $evidenceDir 'micro-step-05-process-metadata.json'
$out | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $path -Encoding UTF8
[ordered]@{ path=$path; process_metadata_available=($null -ne $target); descendant_count=$desc.Count; target_name=$target.Name; target_parent=$target.ParentProcessId; target_flags=$out.target_process.remote_debugging_flags_present } | ConvertTo-Json -Depth 5"
